const RL_BUCKETS = new Map();
function rateLimit({ windowMs = 60000, max = 300, key = "general" } = {}) {
  return (req, res, next) => {
    const ip =
      String(req.headers["cf-connecting-ip"] || req.headers["x-forwarded-for"] || req.socket.remoteAddress || "")
        .split(",")[0]
        .trim() || "unknown";
    const bucketKey = `${key}:${ip}`;
    const now = Date.now();
    let rec = RL_BUCKETS.get(bucketKey);
    if (!rec || now > rec.resetAt) {
      rec = { count: 0, resetAt: now + windowMs };
      RL_BUCKETS.set(bucketKey, rec);
    }
    rec.count += 1;
    const remaining = Math.max(0, max - rec.count);
    res.setHeader("X-RateLimit-Limit", String(max));
    res.setHeader("X-RateLimit-Remaining", String(remaining));
    res.setHeader("X-RateLimit-Reset", String(Math.ceil(rec.resetAt / 1000)));
    if (rec.count > max) {
      res.setHeader("Retry-After", String(Math.ceil((rec.resetAt - now) / 1000)));
      return res.status(429).json({
        ok: false,
        error: "Too many attempts — please try again after 1 minute.",
      });
    }
    next();
  };
}
// हर 5 मिनट में पुराने bucket साफ़ करें
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of RL_BUCKETS) if (now > v.resetAt + 60000) RL_BUCKETS.delete(k);
}, 5 * 60 * 1000);

// ---------- 2) सख़्त CORS ----------
app.use((req, res, next) => {
  const origin = req.headers.origin;
  const allowed = !origin || origin === "null" || APP_ORIGINS.includes(origin);
  if (allowed && origin) {
    res.setHeader("Access-Control-Allow-Origin", origin === "null" ? "null" : origin);
    res.setHeader("Vary", "Origin");
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization, apikey");
    res.setHeader("Access-Control-Max-Age", "86400");
  }
  if (req.method === "OPTIONS") {
    return allowed ? res.status(204).end() : res.status(403).json({ ok: false, error: "Origin not allowed" });
  }
  next();
});

