app.post("/api/users/pair", (req, res) => {
  const myUserId = String(req.body?.myUserId || "").trim();
  const targetQuery = String(req.body?.targetCodeOrId || "").trim();
  if (!targetQuery) return res.status(400).json({ error: "Enter AI Code or phone." });
  const qUpper = targetQuery.toUpperCase();
  const target = Object.values(db.users).find(
    (u) =>
      u.id !== myUserId &&
      (u.id === targetQuery ||
        u.aiCode.toUpperCase() === qUpper ||
        u.identifier.toLowerCase() === targetQuery.toLowerCase() ||
        u.phone.replace(/\s+/g, "") === targetQuery.replace(/\s+/g, ""))
  );
  if (!target) {
    return res.status(404).json({ error: "User not found with that AI Code yet." });
  }
  if (myUserId && db.users[myUserId]) {
    db.pairings[myUserId] = Array.from(new Set([...(db.pairings[myUserId] || []), target.id]));
    db.pairings[target.id] = Array.from(new Set([...(db.pairings[target.id] || []), myUserId]));
    saveDb(db);
    broadcastWs({ type: "user_paired", initiator: sanitizeUser(db.users[myUserId]), targetId: target.id });
  }
  res.json({ ok: true, targetUser: sanitizeUser(target) });
});

