app.get("/api/map/search", async (req, res) => {
  const q = String(req.query.q || "").trim();
  if (!q) return res.json({ ok: true, results: [] });
  try {
    const r = await fetch("https://nominatim.openstreetmap.org/search?format=json&limit=6&addressdetails=1&q=" + encodeURIComponent(q), {
      headers: { "User-Agent": "WrongChatRealMap/2.7", "Accept-Language": "en" },
    });
    const data = await r.json();
    res.json({ ok: true, results: Array.isArray(data) ? data : [] });
  } catch {
    res.json({ ok: false, results: [] });
  }
});

app.get("/api/map/reverse", async (req, res) => {
  const lat = Number(req.query.lat);
  const lng = Number(req.query.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return res.status(400).json({ ok: false });
  try {
    const r = await fetch("https://nominatim.openstreetmap.org/reverse?format=json&zoom=16&lat=" + lat + "&lon=" + lng, {
      headers: { "User-Agent": "WrongChatRealMap/2.7", "Accept-Language": "en" },
    });
    const data = await r.json();
    const addr = data?.address || {};
    const shortLabel = [addr.neighbourhood || addr.suburb || addr.road || addr.village, addr.city || addr.town || addr.state].filter(Boolean).join(", ") || (lat.toFixed(4) + "°, " + lng.toFixed(4) + "°");
    res.json({ ok: true, label: shortLabel });
  } catch {
    res.json({ ok: true, label: lat.toFixed(4) + "°, " + lng.toFixed(4) + "°" });
  }
});

