async function sendEmailOtpCode(email, code) {
  const subject = `${code} — Wrong Chat login code`;
  const html = emailOtpHtml(code);

  if (EMAIL_PROVIDER === "brevo" && BREVO_API_KEY_RESOLVED) {
    await ensureSender();
  }

  if (EMAIL_PROVIDER === "brevo" && BREVO_API_KEY_RESOLVED && EMAIL_FROM) {
    const res = await fetch("https://api.brevo.com/v3/smtp/email", {
      method: "POST",
      headers: {
        "api-key": BREVO_API_KEY_RESOLVED,
        "Content-Type": "application/json",
        accept: "application/json",
      },
      body: JSON.stringify({
        sender: { name: EMAIL_FROM_NAME, email: EMAIL_FROM },
        to: [{ email }],
        subject,
        htmlContent: html,
      }),
    });
    const data = await res.json().catch(() => ({}));
    return { ok: res.ok, provider: "brevo", detail: data };
  }

  if (EMAIL_PROVIDER === "resend" && RESEND_API_KEY_RESOLVED && EMAIL_FROM) {
    const res = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${RESEND_API_KEY_RESOLVED}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        from: `${EMAIL_FROM_NAME} <${EMAIL_FROM}>`,
        to: [email],
        subject,
        html,
      }),
    });
    const data = await res.json().catch(() => ({}));
    return { ok: res.ok, provider: "resend", detail: data };
  }

  // preview — कोड सिर्फ़ सर्वर लॉग में (और EMAIL_OTP_PREVIEW=1 हो तो ऐप में)
  console.log(`📧 [EMAIL OTP PREVIEW] ${email} -> ${code}`);
  return { ok: true, provider: "preview" };
}

async function sendSetupTestEmail(to) {
  const subject = "Wrong Chat — email setup test ✅";
  const html = `<div style="font-family:system-ui;padding:24px"><h2 style="color:#059669">Email OTP is ready ✅</h2><p>This test mail was sent from the Wrong Chat server. If it reached you, email OTP is live.</p><p style="color:#64748b;font-size:13px">Sender: ${EMAIL_FROM} · v3.9.3</p></div>`;
  if (EMAIL_PROVIDER === "brevo" && BREVO_API_KEY_RESOLVED && EMAIL_FROM) {
    try {
      const res = await fetch("https://api.brevo.com/v3/smtp/email", {
        method: "POST",
        headers: { "api-key": BREVO_API_KEY_RESOLVED, "Content-Type": "application/json", accept: "application/json" },
        body: JSON.stringify({ sender: { name: EMAIL_FROM_NAME, email: EMAIL_FROM }, to: [{ email: to }], subject, htmlContent: html }),
      });
      const data = await res.json().catch(() => ({}));
      return {
        ok: res.ok,
        provider: "brevo",
        from: EMAIL_FROM,
        detail: data,
        error: res.ok ? null : (data?.message || "Brevo did not send the mail — check whether the sender is verified."),
      };
    } catch (err) {
      return { ok: false, provider: "brevo", error: "Could not reach Brevo: " + String(err?.message || err) };
    }
  }
  if (EMAIL_PROVIDER === "resend" && RESEND_API_KEY_RESOLVED && EMAIL_FROM) {
    try {
      const res = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: { Authorization: `Bearer ${RESEND_API_KEY_RESOLVED}`, "Content-Type": "application/json" },
        body: JSON.stringify({ from: `${EMAIL_FROM_NAME} <${EMAIL_FROM}>`, to: [to], subject, html }),
      });
      const data = await res.json().catch(() => ({}));
      return { ok: res.ok, provider: "resend", from: EMAIL_FROM, detail: data, error: res.ok ? null : (data?.message || "Resend did not send the mail.") };
    } catch (err) {
      return { ok: false, provider: "resend", error: String(err?.message || err) };
    }
  }
  return { ok: false, error: "No email provider is configured." };
}

app.get("/api/email-otp/diagnose", async (_req, res) => {
  res.setHeader("Cache-Control", "no-store");
  const names = Object.keys(process.env || {})
    .filter((k) => /(brevo|resend|mail|email|sender|from|api|key|otp)/i.test(k))
    .sort();
  const keyPresent = Boolean(BREVO_API_KEY_RESOLVED || RESEND_API_KEY_RESOLVED);
  const keyLooksRight = /^(xkeysib-|re_)/i.test(BREVO_API_KEY_RESOLVED || RESEND_API_KEY_RESOLVED || "");
  let senders = [];
  const account = await brevoAccountCheck();
  if (account.valid) senders = await brevoSenders();
  const hints = [];
  if (SMTP_KEY_FOUND && !keyPresent) {
    hints.push("The key found is an SMTP key (xsmtpsib-) — OTP cannot be sent with it. In Brevo → SMTP & API → API keys & MCP create an xkeysib- API key.");
  }
  if (!keyPresent) {
    hints.push("No variable named BREVO_API_KEY was found in Render → Environment (or it was not saved).");
    hints.push("Note: the Key field must hold BREVO_API_KEY and the Value field the xkeysib-... key — do not swap them.");
  }
  if (keyPresent && !keyLooksRight) hints.push("The key does not start with xkeysib- — copy the whole key again.");
  if (keyPresent && !EMAIL_FROM && senders.length === 0) hints.push("No sender is verified on Brevo — add one at app.brevo.com/senders.");
  if (keyPresent && !EMAIL_FROM && senders.length > 0) hints.push("EMAIL_FROM is not set — the verified Brevo sender is picked automatically.");
  if (EMAIL_FROM) hints.push("Email will be sent from: " + EMAIL_FROM + " (this must be verified in Brevo).");
  let verdict;
  if (!keyPresent && SMTP_KEY_FOUND) verdict = "❌ The key found is an SMTP key (xsmtpsib-) — an xkeysib- API key is needed to send OTP.";
  else if (!keyPresent) verdict = "❌ The key did not reach the server. This server runs service: " + (renderMeta().serviceName || "?") + " (" + (renderMeta().serviceId || "?") + ") — add the key to this service.";
  else if (account.checked && !account.valid) verdict = "❌ Key found but Brevo rejected it: " + account.message;
  else if (account.valid && EMAIL_FROM) verdict = "✅ All set — email OTP is live, mail goes from " + EMAIL_FROM + " .";
  else if (account.valid && !EMAIL_FROM && senders.length > 0) verdict = "✅ Key is valid — the Brevo sender is picked automatically: " + senders[0].email;
  else if (account.valid) verdict = "⚠️ Key is valid but no sender is verified on Brevo — add one at app.brevo.com/senders.";
  else verdict = "⚠️ The key could not be checked (network) — try again.";
  const SYSTEM_ENV = /^(PATH|HOME|HOSTNAME|PORT|PWD|SHLVL|LANG|LC_ALL|TERM|NODE_ENV|NODE_VERSION|NODE_OPTIONS|TZ|USER|SHELL|_|RENDER|RENDER_.*|npm_.*|NPM_.*)$/;
  const allEnvNames = Object.keys(process.env || {}).sort();
  const customEnvNames = allEnvNames.filter((k) => !SYSTEM_ENV.test(k));
  res.json({
    ok: true,
    verdict,
    render: renderMeta(),
    allEnvNames,
    customEnvNames,
    secretFileKeyFound: Boolean(SECRET_FILE_KEY.key),
    enabled: Boolean(EMAIL_OTP_ENABLED),
    provider: EMAIL_PROVIDER,
    keyFound: keyPresent,
    keyValid: Boolean(account.valid),
    keyMessage: account.message,
    smtpKeyFound: Boolean(SMTP_KEY_FOUND),
    keyLength: (BREVO_API_KEY_RESOLVED || "").length,
    keySource: BREVO_DETECT.from !== "none" ? BREVO_DETECT.from : RESEND_DETECT.from,
    keyPrefixOk: keyLooksRight,
    sender: EMAIL_FROM || null,
    senderSource: EMAIL_SENDER_SOURCE,
    brevoSenders: senders,
    envVarNames: names,
    hints,
  });
});

