app.post("/api/email-otp/send", async (req, res) => {
  const email = normalizeEmail(req.body?.email);
  if (!email) {
    return res.status(400).json({ ok: false, error: "Enter a valid email address (e.g. you@gmail.com)." });
  }
  if (!EMAIL_OTP_ENABLED) {
    return res.status(503).json({
      ok: false,
      error: "Email OTP is not enabled yet. Log in with your PIN or tell the Owner.",
    });
  }

  const now = Date.now();
  const rec = emailOtpStore.get(email) || { sentCount: 0, attempts: 0 };
  if (rec.sentAt && now - rec.sentAt < EMAIL_OTP_COOLDOWN_MS) {
    const wait = Math.ceil((EMAIL_OTP_COOLDOWN_MS - (now - rec.sentAt)) / 1000);
    return res.status(429).json({ ok: false, error: `Please send again after ${wait} seconds.`, retryAfterSeconds: wait });
  }
  if (emailToday() >= EMAIL_OTP_DAILY_CAP) {
    return res.status(429).json({ ok: false, error: "Today's email limit is finished — try again tomorrow." });
  }

  const code = freshOtpCode(email); // 🔐 हर बार नया कोड, पर 10 मिनट तक मान्य
  emailOtpDayCount = emailToday() + 1;
  const sent = await sendEmailOtpCode(email, code);
  if (!sent.ok) {
    console.log(`⚠️ Email OTP fail [${sent.provider}]:`, JSON.stringify(sent.detail || {}).slice(0, 200));
    return res.status(502).json({ ok: false, error: "The email could not be sent — try again shortly." });
  }

  emailOtpStore.set(email, {
    hash: emailOtpHash(email, code),
    expiresAt: now + EMAIL_OTP_TTL_MS,
    attempts: 0,
    sentAt: now,
    sentCount: (rec.sentCount || 0) + 1,
  });

  res.json({
    ok: true,
    provider: sent.provider,
    expiresInSeconds: Math.round(EMAIL_OTP_TTL_MS / 1000),
    devOtp: EMAIL_OTP_PREVIEW ? code : undefined,
    message: `Code sent to ${email} (check the Spam folder too).`,
  });
});

app.post("/api/email-otp/verify", (req, res) => {
  const email = normalizeEmail(req.body?.email);
  const code = String(req.body?.code || "").replace(/\D/g, "");
  if (!email) return res.status(400).json({ ok: false, error: "The email is not valid." });
  if (code.length !== 6) return res.status(400).json({ ok: false, error: "Enter the 6-digit code." });

  const rec = emailOtpStore.get(email) || { attempts: 0, sentCount: 0 };

  // 1) समय-आधारित कोड — पिछले 10 मिनट के किसी भी सेकंड का कोड चलेगा
  //    (सर्वर restart / नई deploy हो जाए, तब भी काम करेगा)
  const timeMatch = isRecentOtpCode(email, code);
  // 2) साथ ही RAM में सेव कोड भी (पुराने तरीके से भेजे गए कोड के लिए)
  const sentMatch =
    Boolean(rec.hash) && Boolean(rec.expiresAt) && Date.now() <= rec.expiresAt && rec.hash === emailOtpHash(email, code);
  if (!timeMatch && !sentMatch) {
    rec.attempts += 1;
    emailOtpStore.set(email, { ...rec, attempts: rec.attempts });
    return res.status(400).json({
      ok: false,
      error: `Code not found! Attempts left: ${Math.max(0, EMAIL_OTP_MAX_ATTEMPTS - rec.attempts)} — send a new code or enter the correct 6 digits.`,
      attemptsLeft: Math.max(0, EMAIL_OTP_MAX_ATTEMPTS - rec.attempts),
    });
  }

  emailOtpStore.delete(email);
  const issued = Date.now();
  const sig = crypto
    .createHmac("sha256", OTP_SECRET)
    .update(`mail|${email}|${issued}`)
    .digest("hex")
    .slice(0, 32);
  res.json({ ok: true, token: `${issued}.${sig}`, email, verifiedAt: issued });
});

